    resource("lb", { tags: { branch: "feat-a" }, depends_on: ["network"], type: "load_balancer" }),
    // Put CDK resources beyond the first API page, as in INFRA-741.
    ...Array.from({ length: 18 }, (_, i) => resource(`other-${i}`, { tags: { branch: "feat-other" } })),
