    resource("other-cdk", { labels: { Branch: "feat-other" } }),
    resource("case-sensitive-value", { labels: { Branch: "Feat-A" } }),
    resource("tag-precedence", { tags: { branch: "feat-other" }, labels: { Branch: "feat-a" } }),
  ];
}

const expected = ["boot", "cdk-dns", "cdk-instance", "cdk-volume", "lb", "network"];

async function runCli(args: string[], initial = fixture()) {
  const resources = structuredClone(initial);
  const deleted: string[] = [];
  const cursors: string[] = [];
  const server = createServer((req, res) => {
    res.setHeader("content-type", "application/json");
    const url = new URL(req.url!, "http://localhost");
    if (req.method === "GET" && url.pathname === "/v1/resources") {
      const cursor = url.searchParams.get("cursor")!;
      cursors.push(cursor);
      const start = Number(cursor);
      assert.equal(url.searchParams.get("limit"), "20");
      res.end(JSON.stringify({ resources: resources.slice(start, start + 20), next_cursor: start + 20 < resources.length ? String(start + 20) : null }));
      return;
    }
    if (req.method === "DELETE" && url.pathname.startsWith("/v1/resources/")) {
      const id = decodeURIComponent(url.pathname.slice("/v1/resources/".length));
      const dependents = resources.filter(r => r.depends_on.includes(id)).map(r => r.id);
      if (dependents.length) {
        res.statusCode = 409;
        res.end(JSON.stringify({ error: "resource has dependents", dependents }));
        return;
      }
      const index = resources.findIndex(r => r.id === id);
      if (index < 0) {
        res.statusCode = 404;
        res.end(JSON.stringify({ error: "not found" }));
        return;
      }
      resources.splice(index, 1);
      deleted.push(id);
      res.end(JSON.stringify({ deleted: id }));
      return;
    }
    res.statusCode = 404;
    res.end(JSON.stringify({ error: "unexpected request" }));
  });
  await new Promise<void>(resolve => server.listen(0, "127.0.0.1", resolve));
  try {
    const address = server.address();
    assert.ok(address && typeof address !== "string");
    const child = spawn(process.execPath, ["--experimental-strip-types", "--no-warnings", new URL("../src/cli.ts", import.meta.url).pathname, ...args], {
      env: { ...process.env, ENVCTL_API: `http://127.0.0.1:${address.port}`, ENVCTL_TOKEN: "test-token" },
      stdio: ["ignore", "pipe", "pipe"],
    });
    let stdout = "", stderr = "";
    child.stdout.on("data", chunk => { stdout += chunk; });
    child.stderr.on("data", chunk => { stderr += chunk; });
    const code = await new Promise<number | null>((resolve, reject) => {
      child.on("error", reject);
      child.on("close", resolve);
    });
    return { code, stdout, stderr, resources, deleted, cursors };
  } finally {
    await new Promise<void>((resolve, reject) => server.close(err => err ? reject(err) : resolve()));
  }
