test("CLI plan recognizes labels across pages without widening branch ownership", async () => {
  const result = await runCli(["plan", "--branch", "feat-a", "--json"]);
  assert.equal(result.code, 0, result.stderr);
  assert.deepEqual(result.cursors, ["0", "20"]);
  const plan = JSON.parse(result.stdout);
  assert.deepEqual(plan.steps.map((r: { id: string }) => r.id).sort(), expected);
  assert.deepEqual(plan.blocked, []);
  assert.deepEqual(result.deleted, []);
  const positions = new Map(plan.steps.map((r: { id: string }, i: number) => [r.id, i]));
  for (const r of fixture().filter(r => positions.has(r.id))) {
    for (const dependency of r.depends_on) {
      assert.ok(Number(positions.get(r.id)) < Number(positions.get(dependency)));
    }
  }
});

test("CLI list groups label-owned resources instead of reporting them as untagged", async () => {
  const result = await runCli(["list"]);
  assert.equal(result.code, 0, result.stderr);
  assert.match(result.stdout, /feat-a\s+5\s/);
  assert.match(result.stdout, /feat-other\s+20\s/);
  assert.match(result.stdout, /Feat-A\s+1\s/);
  assert.match(result.stdout, /1 untagged resources/); // stack-created boot volume
});

test("CLI teardown deletes all and only branch resources, dependents first", async () => {
