  assert.deepEqual([...result.deleted].sort(), expected);
  assert.deepEqual(result.resources, fixture().filter(r => !expected.includes(r.id)));
  assert.match(result.stdout, /complete \(6 resources\)/);
});

test("CLI dry-run recognizes labels but does not delete resources", async () => {
