  assert.match(result.stdout, /network is still used by external/);
  assert.match(result.stderr, /refusing to tear down/);
  assert.deepEqual(result.deleted, []);
  assert.deepEqual(result.resources, initial);
});

test("CLI gc does not treat label-owned resources as untagged", async () => {
  const result = await runCli(["gc", "--untagged"]);
  assert.equal(result.code, 0, result.stderr);
  assert.match(result.stdout, /^1 untagged resources/);
  assert.deepEqual(result.deleted, []);
});
